def _encode_json_value(value: Any) -> tuple[int, bytes]:
    """Deterministically tag a JSON scalar query for the receipt encoding."""
    if isinstance(value, bool):
        return (_JSON_TAG_TRUE if value else _JSON_TAG_FALSE), b""
    if value is None:
        return _JSON_TAG_NULL, b""
    if isinstance(value, str):
        return _JSON_TAG_STRING, value.encode("utf-8")
    if isinstance(value, int):
        # Canonical decimal spelling handles every integer width and sign.
        return _JSON_TAG_INTEGER, str(value).encode("ascii")
    # float: repr round-trips the exact binary value (Python >= 3.1).
    return _JSON_TAG_FLOAT, repr(value).encode("ascii")


def _decode_json_value(tag: int, blob: bytes) -> Any:
    if tag == _JSON_TAG_STRING:
        try:
            return blob.decode("utf-8")
        except UnicodeDecodeError as error:
            raise ValueError("encoded JSON string value is not valid UTF-8") from error
    if tag == _JSON_TAG_INTEGER:
        try:
            text = blob.decode("ascii")
        except UnicodeDecodeError as error:
            raise ValueError("encoded JSON integer value is not ASCII decimal") from error
        digits = text[1:] if text[:1] == "-" else text
        if not digits or any(ch not in "0123456789" for ch in digits):
            raise ValueError("encoded JSON integer value is not canonical decimal")
        return int(text)
    if tag == _JSON_TAG_FLOAT:
        try:
            text = blob.decode("ascii")
        except UnicodeDecodeError as error:
            raise ValueError("encoded JSON float value is not ASCII") from error
        try:
            value = float(text)
        except ValueError as error:
            raise ValueError("encoded JSON float value is not a number") from error
        if not math.isfinite(value):
            raise ValueError("encoded JSON float value must be finite")
        return value
    if tag == _JSON_TAG_TRUE:
        if blob:
            raise ValueError("a boolean JSON value must carry an empty blob")
        return True
    if tag == _JSON_TAG_NULL:
        if blob:
            raise ValueError("a null JSON value must carry an empty blob")
        return None
    if tag == _JSON_TAG_FALSE:
        if blob:
            raise ValueError("a boolean JSON value must carry an empty blob")
        return False
    raise ValueError(f"unknown JSON value type tag {tag}")


def encode_json_search_receipt(receipt: Any) -> bytes:
    """Encode a :class:`JsonSearchReceipt` into its canonical binary form.

def _check_key(key: Any) -> bytes:
    if not isinstance(key, bytes):
        raise TypeError("key must be bytes")
    if len(key) != _KEY_BYTES:
        raise ValueError(f"key must be {_KEY_BYTES} bytes")
    return key


def _check_nonce(nonce: Any) -> bytes:
    if not isinstance(nonce, bytes):
        raise TypeError("nonce must be bytes")
    if len(nonce) != _NONCE_BYTES:
        raise ValueError(f"nonce must be {_NONCE_BYTES} bytes")
    return nonce


def _load_ed25519_seed(private_key: Any) -> Ed25519PrivateKey:
    """Load a 32-byte Ed25519 private key seed; the seed is never stored."""
    if not isinstance(private_key, bytes):
        raise TypeError("private_key must be a 32-byte Ed25519 seed")
    if len(private_key) != _ED25519_KEY_BYTES:
        raise ValueError(
            f"private_key must be {_ED25519_KEY_BYTES} bytes (an Ed25519 seed)"
        )
    return Ed25519PrivateKey.from_private_bytes(private_key)


def _load_ed25519_public(public_key: Any) -> Ed25519PublicKey:
    if not isinstance(public_key, bytes):
        raise TypeError("public_key must be a 32-byte Ed25519 public key")
    if len(public_key) != _ED25519_KEY_BYTES:
        raise ValueError(
            f"public_key must be {_ED25519_KEY_BYTES} bytes (an Ed25519 public key)"
        )
    return Ed25519PublicKey.from_public_bytes(public_key)


def _signed_root_message(hash_name: str, size: int, root: bytes, head: bytes) -> bytes:
    """M of sign_root / verify_signed_root.

    ``D || 0x01 || B(UTF-8(hash_name)) || U(size) || B(root) || B(head)``
    with ``D = b"auditchain/signed-root/v1\\0"``, ``U`` an unsigned 8-byte
    big-endian integer and ``B(x) = U(len(x)) || x``.
    """
    return (
        _SIGNED_ROOT_DOMAIN
        + bytes((0x01,))
        + _encode_blob(hash_name.encode("utf-8"))
        + _encode_u64(size, "size")
        + _encode_blob(root)
        + _encode_blob(head)
    )


def _signed_range_search_message(receipt_blob: bytes) -> bytes:
    """M of signed_range_search_receipt / verify_signed_range_search_receipt.

    ``D || 0x01 || B(receipt_blob)`` with
    ``D = b"auditchain/signed-range-search/v1\\0"`` and
    ``B(x) = U(len(x)) || x``; ``receipt_blob`` is the complete canonical

def _json_entry_scalar(payload: bytes, tokens: tuple[str, ...]) -> Any:
    """The addressed scalar of one stored payload, or ``_JSON_MISSING``.

    Same resolution rules as :func:`_json_entry_matches` — an AES-256-GCM
    envelope is never parsed — but returns the resolved scalar itself so the
    JSON field retrieval index can group entries by their addressed value.
    """
    if payload.startswith(_ENC_MAGIC):
